CREATE DATABASE IF NOT EXISTS personal_study_planner;
USE personal_study_planner;
CREATE TABLE users (user_id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, available_hours_per_day DECIMAL(4,2) NOT NULL CHECK (available_hours_per_day BETWEEN 0 AND 24), preferred_start_time TIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE subjects (subject_id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, subject_name VARCHAR(100) NOT NULL, description VARCHAR(255), UNIQUE(user_id,subject_name), FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE);
CREATE TABLE topics (topic_id INT PRIMARY KEY AUTO_INCREMENT, subject_id INT NOT NULL, topic_name VARCHAR(150) NOT NULL, difficulty TINYINT NOT NULL CHECK(difficulty BETWEEN 1 AND 5), importance TINYINT NOT NULL CHECK(importance BETWEEN 1 AND 5), estimated_minutes INT NOT NULL CHECK(estimated_minutes>0), deadline DATE, progress TINYINT NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100), status ENUM('NOT_STARTED','IN_PROGRESS','COMPLETED') NOT NULL DEFAULT 'NOT_STARTED', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE(subject_id,topic_name), FOREIGN KEY(subject_id) REFERENCES subjects(subject_id) ON DELETE CASCADE, INDEX idx_topics_deadline(deadline), INDEX idx_topics_status(status));
CREATE TABLE study_sessions (session_id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NOT NULL,topic_id INT NOT NULL,study_date DATE NOT NULL,start_time TIME,duration_minutes INT NOT NULL,status ENUM('PLANNED','COMPLETED','MISSED') NOT NULL DEFAULT 'PLANNED',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(topic_id) REFERENCES topics(topic_id),INDEX idx_study_date(study_date));
CREATE TABLE revision_sessions (revision_id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NOT NULL,topic_id INT NOT NULL,revision_number INT NOT NULL,scheduled_date DATE NOT NULL,status ENUM('PLANNED','COMPLETED','MISSED') NOT NULL DEFAULT 'PLANNED',FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(topic_id) REFERENCES topics(topic_id));
CREATE TABLE pyq_questions (question_id INT PRIMARY KEY AUTO_INCREMENT,subject_id INT NOT NULL,topic_id INT,question_text TEXT NOT NULL,source_year INT NOT NULL,difficulty ENUM('BASIC','INTERMEDIATE','ADVANCED') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(subject_id) REFERENCES subjects(subject_id),FOREIGN KEY(topic_id) REFERENCES topics(topic_id));
CREATE TABLE topic_keywords (keyword_id INT PRIMARY KEY AUTO_INCREMENT,topic_id INT NOT NULL,keyword VARCHAR(100) NOT NULL,UNIQUE(topic_id,keyword),FOREIGN KEY(topic_id) REFERENCES topics(topic_id) ON DELETE CASCADE);
CREATE TABLE practice_questions (practice_id INT PRIMARY KEY AUTO_INCREMENT,topic_id INT NOT NULL,question_text TEXT NOT NULL,difficulty ENUM('BASIC','INTERMEDIATE','ADVANCED') NOT NULL,question_type ENUM('MCQ','SHORT','CODING','PYQ') NOT NULL,FOREIGN KEY(topic_id) REFERENCES topics(topic_id) ON DELETE CASCADE);
CREATE TABLE performance_records (performance_id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NOT NULL,topic_id INT NOT NULL,total_questions INT NOT NULL,correct_answers INT NOT NULL,score_percentage DECIMAL(5,2) NOT NULL,confidence_level TINYINT NOT NULL CHECK(confidence_level BETWEEN 1 AND 5),attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id),FOREIGN KEY(topic_id) REFERENCES topics(topic_id));
CREATE TABLE resources (resource_id INT PRIMARY KEY AUTO_INCREMENT,topic_id INT NOT NULL,resource_name VARCHAR(200) NOT NULL,resource_type ENUM('TUTORIAL','VIDEO','PRACTICE','REVISION') NOT NULL,url VARCHAR(500),difficulty_level VARCHAR(50),FOREIGN KEY(topic_id) REFERENCES topics(topic_id) ON DELETE CASCADE);
